DIRECTIONS = ((-1, 0), (1, 0), (0, -1), (0, 1))


def find_tile(grid: list[list[int]], tile: int) -&gt; tuple[int, int]:
    for row, values in enumerate(grid):
        for col, value in enumerate(values):
            if value == tile:
                return row, col
    raise ValueError(f"tile {tile} is missing")


def neighbors(
    row: int, col: int, height: int, width: int
):
    for d_row, d_col in DIRECTIONS:
        next_row = row + d_row
        next_col = col + d_col
        if 0 &lt;= next_row &lt; height and 0 &lt;= next_col &lt; width:
            yield next_row, next_col






NoteOptional local path checker





Keep this checker in a separate file such as check_hw1.py; do not paste it into the submitted hw1.py. It checks the path format and simulates keys and doors without changing the original grid. It does not prove that a legal path is shortest.
from hw1 import Solution

ROAD, DOOR, WALL, KEY, EXIT, PLAYER = range(6)


def path_is_legal(grid, path):
    if not path:
        return False

    board = [row[:] for row in grid]
    height = len(board)
    width = len(board[0])

    start = next(
        (r, c)
        for r, row in enumerate(board)
        for c, tile in enumerate(row)
        if tile == PLAYER
    )
    goal = next(
        (r, c)
        for r, row in enumerate(board)
        for c, tile in enumerate(row)
        if tile == EXIT
    )

    if path[0] != start:
        return False

    keys = 0
    previous = start
    for step in path[1:]:
        if not (
            isinstance(step, tuple)
            and len(step) == 2
            and all(isinstance(value, int) for value in step)
        ):
            return False

        row, col = step
        if not (0 &lt;= row &lt; height and 0 &lt;= col &lt; width):
            return False
        if abs(row - previous[0]) + abs(col - previous[1]) != 1:
            return False

        tile = board[row][col]
        if tile == WALL:
            return False
        if tile == KEY:
            keys += 1
            board[row][col] = ROAD
        elif tile == DOOR:
            if keys == 0:
                return False
            keys -= 1
            board[row][col] = ROAD

        previous = step

    return path[-1] == goal


example = [
    [4, 2, 1, 3],
    [0, 5, 0, 2],
    [2, 3, 1, 0],
]
result = Solution().shortest_path([row[:] for row in example])
assert path_is_legal(example, result)
assert len(result) == 3

